import{c as s,Q as a,j as e,m as n}from"./chunks/framework.DoOjWOm2.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/install-from-url.md","filePath":"plugins/install-from-url.md"}'),t={name:"plugins/install-from-url.md"};function l(r,i,h,p,o,d){return a(),e("div",null,[...i[0]||(i[0]=[n(`<p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.14 <strong>Since:</strong> 0.18.0</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Install any public plugin by pasting its <code>plugin.json</code> URL into Phlix. Two prerequisites: an admin account on the server and the plugin&#39;s HTTPS URL. The plugin lands <strong>disabled</strong> after install — flip the toggle to enable it. For curated, signature-verified plugins in one click, use the <a href="./install-from-catalog.html">catalog</a> instead.</p><hr><h2 id="_1-prerequisites" tabindex="-1">1. Prerequisites <a class="header-anchor" href="#_1-prerequisites" aria-label="Permalink to &quot;1. Prerequisites&quot;">​</a></h2><ul><li><strong>Admin account</strong> on the Phlix server (<code>users.is_admin = 1</code>).</li><li><strong>Plugin&#39;s public <code>plugin.json</code> URL</strong> — must be HTTPS (<code>http://</code> refused unless <code>PHLIX_PLUGINS_ALLOW_HTTP=1</code>).</li><li><strong>Optional:</strong> signed plugins need their author key in the <a href="./trusted-plugin-list.html">trusted-key allowlist</a>.</li></ul><hr><h2 id="_2-install-from-the-web-ui" tabindex="-1">2. Install from the Web UI <a class="header-anchor" href="#_2-install-from-the-web-ui" aria-label="Permalink to &quot;2. Install from the Web UI&quot;">​</a></h2><ol><li>Browse to <strong>Settings → Plugins</strong> (or <code>/admin/plugins</code>).</li><li>Locate <strong>Install from URL</strong> panel.</li><li>Paste the plugin&#39;s <code>plugin.json</code> URL.</li><li>Click <strong>Install</strong>.</li><li>Wait for the server to download, validate, and stage the plugin.</li><li>Find the plugin in the table — it lands <strong>disabled</strong> by default.</li><li>Flip the toggle to enable it.</li></ol><p>Screenshot placeholder: <code>[screenshot: admin/plugins table with phlix-plugin-example row, toggle off]</code></p><hr><h2 id="_3-install-from-the-command-line" tabindex="-1">3. Install from the Command Line <a class="header-anchor" href="#_3-install-from-the-command-line" aria-label="Permalink to &quot;3. Install from the Command Line&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…your admin bearer token…&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Install from URL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://phlix.example.com/api/v1/admin/plugins/install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;url&quot;: &quot;https://example.com/my-plugin/plugin.json&quot;}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://phlix.example.com/api/v1/admin/plugins/my-plugin/enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. List installed plugins</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://phlix.example.com/api/v1/admin/plugins</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Disable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://phlix.example.com/api/v1/admin/plugins/my-plugin/disable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. Uninstall</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://phlix.example.com/api/v1/admin/plugins/my-plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><hr><h2 id="_4-reference-plugin-walkthrough" tabindex="-1">4. Reference Plugin Walkthrough <a class="header-anchor" href="#_4-reference-plugin-walkthrough" aria-label="Permalink to &quot;4. Reference Plugin Walkthrough&quot;">​</a></h2><p>Try the install flow on a fresh server using the reference plugin:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/detain/phlix-plugin-example/main/plugin.json</span></span></code></pre></div><p>Steps: paste → Install → toggle Enable → confirm in the plugins table. The reference plugin (<code>phlix-plugin-example</code>) is a minimal <code>metadata-provider</code> that returns <code>{&quot;title&quot;: &quot;Hello, World&quot;}</code> for a known fixture path — safe to install on any environment.</p><hr><h2 id="_5-plugin-settings" tabindex="-1">5. Plugin Settings <a class="header-anchor" href="#_5-plugin-settings" aria-label="Permalink to &quot;5. Plugin Settings&quot;">​</a></h2><p>After install, click <strong>Settings</strong> (wrench icon) next to any enabled plugin to open its per-plugin settings form. Settings are persisted in <code>plugins.settings_json</code>. Each plugin exposes its own fields (API keys, endpoint URLs, etc.) as declared in its <code>plugin.json</code> <code>settings</code> block.</p><hr><h2 id="_6-what-can-go-wrong" tabindex="-1">6. What Can Go Wrong <a class="header-anchor" href="#_6-what-can-go-wrong" aria-label="Permalink to &quot;6. What Can Go Wrong&quot;">​</a></h2><h3 id="failure-1-version-incompatibility" tabindex="-1">Failure 1: Version Incompatibility <a class="header-anchor" href="#failure-1-version-incompatibility" aria-label="Permalink to &quot;Failure 1: Version Incompatibility&quot;">​</a></h3><p><strong>Symptom:</strong> <code>422</code> / <code>plugin.install.failed</code> with <code>phlix_min_server_version</code> in <code>fields[]</code>.</p><p><strong>Cause:</strong> Running server is older than what the plugin requires.</p><p><strong>Fix:</strong> Upgrade phlix-server first, or choose a different plugin version.</p><hr><h3 id="failure-2-signature-verification-failure" tabindex="-1">Failure 2: Signature Verification Failure <a class="header-anchor" href="#failure-2-signature-verification-failure" aria-label="Permalink to &quot;Failure 2: Signature Verification Failure&quot;">​</a></h3><p><strong>Symptom:</strong> <code>422</code> / <code>plugin.signature.mismatch</code>.</p><p><strong>Cause:</strong> Downloaded tarball was corrupted in transit, or the plugin was tampered with.</p><p><strong>Fix:</strong> Re-download the plugin, or check with the plugin author that the signature is current.</p><hr><h3 id="failure-3-plugin-requires-restart" tabindex="-1">Failure 3: Plugin Requires Restart <a class="header-anchor" href="#failure-3-plugin-requires-restart" aria-label="Permalink to &quot;Failure 3: Plugin Requires Restart&quot;">​</a></h3><p><strong>Symptom:</strong> Plugin listener never fires even after enable.</p><p><strong>Cause:</strong> Some plugins (<code>transcoder-hook</code>, <code>ui-theme</code>) register hooks only at server boot, not on enable.</p><p><strong>Fix:</strong> Restart phlix-server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phlix</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><hr><h3 id="failure-4-ui-theme-css-breaks-web-portal" tabindex="-1">Failure 4: ui-theme CSS Breaks Web Portal <a class="header-anchor" href="#failure-4-ui-theme-css-breaks-web-portal" aria-label="Permalink to &quot;Failure 4: ui-theme CSS Breaks Web Portal&quot;">​</a></h3><p><strong>Symptom:</strong> Web portal blank or unstyled after enabling a <code>ui-theme</code>.</p><p><strong>Cause:</strong> Theme&#39;s CSS conflicts with current portal version.</p><p><strong>Fix:</strong> Disable via CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://phlix.example.com/api/v1/admin/plugins/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/disable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Then contact the plugin author.</p><hr><h2 id="_7-next-steps" tabindex="-1">7. Next Steps <a class="header-anchor" href="#_7-next-steps" aria-label="Permalink to &quot;7. Next Steps&quot;">​</a></h2><ul><li><a href="./install-from-catalog.html">Browse the plugin catalog</a> — for curated, signature-verified plugins in one click</li><li><a href="./trusted-plugin-list.html">Trusted plugin list</a> — add an author&#39;s signing key to the allowlist</li><li><a href="./developer-guide.html">Plugin developer guide</a> — for plugin authors; understand what types exist and how to implement them</li><li><a href="./developer-guide.html#faq--troubleshooting">Troubleshooting</a> — common plugin errors and <code>.logs/</code> exploration</li></ul><hr><h2 id="security-notes" tabindex="-1">Security Notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security Notes&quot;">​</a></h2><ul><li><strong>HTTPS only by default.</strong> The controller refuses <code>http://</code> even when <code>PHLIX_PLUGINS_ALLOW_HTTP=1</code> is set elsewhere.</li><li><strong>Signatures are honoured.</strong> If the manifest declares a <code>sha256:…</code> signature, install fails unless that signature appears in the <a href="./trusted-plugin-list.html">trusted-key allowlist</a>. Unsigned plugins install with a warning in the <code>plugins</code> log channel.</li><li><strong>CSRF is not required.</strong> The API is Bearer-token authenticated. Browsers do not auto-attach Authorization headers across origins.</li><li><strong>Every install / enable / disable / uninstall is audit-logged.</strong> Entries land in the <code>AUTH</code> log channel with the actor user id and action name. See <code>docs/dev/architecture-server.md</code> for log paths.</li></ul>`,51)])])}const u=s(t,[["render",l]]);export{k as __pageData,u as default};
